usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Containers.Files.List(
		context.TODO(),
		"container_id",
		openai.ContainerFileListParams{
			Limit: param.NewOpt[int64](20),
			Order: param.NewOpt[openai.ContainersFilesListOrder](openai.ContainersFilesListOrderAsc),
			After: param.NewOpt[string]("after"),
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
